style.css:
@-moz-document domain("chat.deepseek.com"), domain("deepseek.com") {
/* ============================================
   ROOT VARIABLES - BLUE OVERRIDE TO PURPLE
   ============================================ */
:root {
    --ds-primary: #9b30ff !important;
    --ds-primary-light: #b860ff !important;
    --ds-primary-dark: #7a1fa8 !important;
    --ds-primary-darker: #5a0f7a !important;
    --ds-background: #000000 !important;
    --ds-background-secondary: #0a0a0a !important;
    --ds-surface: #0f0f0f !important;
    --ds-surface-hover: #1a1a1a !important;
    --ds-border: #2a2a2a !important;
    --ds-text: #e5e5e5 !important;
    --ds-text-secondary: #a0a0a0 !important;
}

/* ============================================
   BACKGROUND OVERRIDE - AMOLED BLACK
   ============================================ */
body, #root, .app, main, div[class*="bg-white"],
div[class*="bg-gray"], div[class*="bg-zinc"] {
    background-color: #000000 !important;
    background-image: none !important;
}

/* ============================================
   TEXT COLOR - LIGHT GRAY
   ============================================ */
body, div, span, p, h1, h2, h3, h4, h5, h6,
li, label, .text-gray, .text-gray-500, .text-gray-600,
.text-gray-700, .text-gray-800, .text-gray-900 {
    color: #e5e5e5 !important;
}

/* ============================================
   CORE BLUE TO PURPLE - TEXT COLORS
   ============================================ */
.text-blue-50, .text-blue-100, .text-blue-200, .text-blue-300,
.text-blue-400, .text-blue-500, .text-blue-600, .text-blue-700,
.text-blue-800, .text-blue-900, .text-sky-500, .text-sky-600,
.text-indigo-500, .text-indigo-600, [class*="text-blue"],
[class*="text-sky"], [class*="text-indigo"] {
    color: #b860ff !important;
}

.text-blue-700, .text-blue-800, .text-sky-700 {
    color: #9b30ff !important;
}

/* ============================================
   BLUE TO PURPLE - BACKGROUNDS
   ============================================ */
.bg-blue-50, .bg-blue-100, .bg-blue-200, .bg-blue-300,
.bg-blue-400, .bg-blue-500, .bg-blue-600, .bg-blue-700,
.bg-blue-800, .bg-blue-900, .bg-sky-500, .bg-sky-600,
.bg-indigo-500, .bg-indigo-600, [class*="bg-blue"],
[class*="bg-sky"], [class*="bg-indigo"] {
    background-color: #9b30ff !important;
}

/* ============================================
   BLUE TO PURPLE - BORDERS
   ============================================ */
.border-blue-50, .border-blue-100, .border-blue-200, .border-blue-300,
.border-blue-400, .border-blue-500, .border-blue-600, .border-blue-700,
.border-blue-800, .border-blue-900, .border-sky-500, .border-sky-600,
[class*="border-blue"], [class*="border-sky"], [class*="border-indigo"] {
    border-color: #9b30ff !important;
}

/* ============================================
   BLUE TO PURPLE - RINGS (Focus states)
   ============================================ */
.ring-blue-300, .ring-blue-400, .ring-blue-500, .ring-blue-600,
.ring-sky-500, [class*="ring-blue"], [class*="ring-sky"] {
    --tw-ring-color: #9b30ff !important;
}

/* ============================================
   BLUE TO PURPLE - GRADIENTS
   ============================================ */
.from-blue-500, .from-blue-600, .from-sky-500, .from-indigo-500,
[class*="from-blue"], [class*="from-sky"] {
    --tw-gradient-from: #9b30ff !important;
    --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to, rgba(155, 48, 255, 0)) !important;
}

.to-blue-500, .to-blue-600, .to-sky-500,
[class*="to-blue"], [class*="to-sky"] {
    --tw-gradient-to: #7a1fa8 !important;
}

/* ============================================
   BLUE TO PURPLE - HOVER STATES
   ============================================ */
.hover\:text-blue-600:hover,
.hover\:text-blue-700:hover {
    color: #b860ff !important;
}

.hover\:bg-blue-50:hover,
.hover\:bg-blue-100:hover,
.hover\:bg-blue-500:hover,
.hover\:bg-blue-600:hover {
    background-color: #7a1fa8 !important;
}

/* ============================================
   BUTTON & INTERACTIVE ELEMENTS
   ============================================ */
button[class*="bg-blue"], 
button[class*="bg-primary"],
[role="button"][class*="bg-blue"] {
    background-color: #9b30ff !important;
}

button[class*="bg-blue"]:hover,
button[class*="bg-primary"]:hover {
    background-color: #7a1fa8 !important;
}

/* ============================================
   LINK COLORS
   ============================================ */
a, [role="link"] {
    color: #b860ff !important;
}

a:hover, [role="link"]:hover {
    color: #9b30ff !important;
}

/* ============================================
   INPUT FIELDS - DARK THEME
   ============================================ */
input, textarea, select, [contenteditable="true"] {
    background-color: #0a0a0a !important;
    border-color: #2a2a2a !important;
    color: #e5e5e5 !important;
}

input:focus, textarea:focus, select:focus, [contenteditable="true"]:focus {
    border-color: #9b30ff !important;
    outline: none !important;
    box-shadow: 0 0 0 2px rgba(155, 48, 255, 0.2) !important;
}

/* ============================================
   SCROLLBAR STYLING
   ============================================ */
::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

::-webkit-scrollbar-track {
    background: #0a0a0a;
}

::-webkit-scrollbar-thumb {
    background: #2a2a2a;
    border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
    background: #9b30ff;
}

/* ============================================
   MESSAGE BUBBLES & CHAT ELEMENTS
   ============================================ */
[class*="message"], [class*="chat-message"], 
[class*="bubble"], [class*="conversation"] {
    background-color: #0f0f0f !important;
    border-color: #2a2a2a !important;
}

[class*="user-message"], [class*="user-bubble"] {
    background-color: #1a1a1a !important;
}

[class*="assistant-message"], [class*="ai-message"] {
    background-color: #0f0f0f !important;
}

/* ============================================
   SIDEBAR & NAVIGATION
   ============================================ */
[class*="sidebar"], [class*="nav"], [class*="drawer"] {
    background-color: #000000 !important;
    border-color: #2a2a2a !important;
}

[class*="sidebar-item"]:hover, [class*="nav-item"]:hover {
    background-color: #1a1a1a !important;
}

[class*="sidebar-item"][class*="active"], 
[class*="nav-item"][class*="active"] {
    background-color: #9b30ff20 !important;
    border-left-color: #9b30ff !important;
}

/* ============================================
   CODE BLOCKS
   ============================================ */
pre, code, [class*="code-block"] {
    background-color: #0a0a0a !important;
    border-color: #2a2a2a !important;
    color: #e5e5e5 !important;
}

/* ============================================
   LOADING SPINNERS & PROGRESS
   ============================================ */
[class*="spinner"], [class*="loader"] {
    border-color: #2a2a2a !important;
    border-top-color: #9b30ff !important;
}

[class*="progress"] {
    background-color: #9b30ff !important;
}

/* ============================================
   TOAST NOTIFICATIONS
   ============================================ */
[class*="toast"], [class*="notification"] {
    background-color: #1a1a1a !important;
    border-color: #9b30ff !important;
}

/* ============================================
   DROPDOWN MENUS
   ============================================ */
[class*="dropdown"], [class*="menu"] {
    background-color: #0f0f0f !important;
    border-color: #2a2a2a !important;
}

[class*="dropdown-item"]:hover, [class*="menu-item"]:hover {
    background-color: #9b30ff !important;
    color: #ffffff !important;
}

/* ============================================
   MODAL DIALOGS
   ============================================ */
[class*="modal"], [class*="dialog"] {
    background-color: #0a0a0a !important;
    border-color: #2a2a2a !important;
}

[class*="modal-header"], [class*="dialog-header"] {
    border-bottom-color: #2a2a2a !important;
}

[class*="modal-footer"], [class*="dialog-footer"] {
    border-top-color: #2a2a2a !important;
}

/* ============================================
   TAB COMPONENTS
   ============================================ */
[class*="tab-active"], [class*="tab-selected"] {
    color: #b860ff !important;
    border-bottom-color: #9b30ff !important;
}

[class*="tab"]:hover {
    color: #b860ff !important;
}

/* ============================================
   ACCENT COLOR OVERRIDES
   ============================================ */
.accent, [class*="accent"] {
    color: #9b30ff !important;
}

.accent-bg, [class*="accent-bg"] {
    background-color: #9b30ff !important;
}

/* ============================================
   PLACEHOLDER TEXT
   ============================================ */
::placeholder, [placeholder] {
    color: #6a6a6a !important;
    opacity: 1 !important;
}

/* ============================================
   SELECTION HIGHLIGHT
   ============================================ */
::selection {
    background-color: #9b30ff !important;
    color: #ffffff !important;
}

::-moz-selection {
    background-color: #9b30ff !important;
    color: #ffffff !important;
}

/* ============================================
   FOCUS VISIBLE ACCESSIBILITY
   ============================================ */
:focus-visible {
    outline: 2px solid #9b30ff !important;
    outline-offset: 2px !important;
}

/* ============================================
   DIVIDER LINES
   ============================================ */
hr, [class*="divider"], [class*="separator"] {
    background-color: #2a2a2a !important;
    border-color: #2a2a2a !important;
}

/* ============================================
   BADGE & TAG COMPONENTS
   ============================================ */
[class*="badge"], [class*="tag"] {
    background-color: #9b30ff20 !important;
    color: #b860ff !important;
    border-color: #9b30ff40 !important;
}

/* ============================================
   TOGGLE SWITCHES
   ============================================ */
[class*="toggle"][class*="active"], 
[class*="switch"][class*="checked"] {
    background-color: #9b30ff !important;
}

[class*="toggle"]:checked, 
[class*="switch"]:checked {
    background-color: #9b30ff !important;
}

/* ============================================
   RADIO & CHECKBOX
   ============================================ */
input[type="radio"]:checked,
input[type="checkbox"]:checked {
    accent-color: #9b30ff !important;
}

/* ============================================
   SLIDER INPUT
   ============================================ */
input[type="range"] {
    accent-color: #9b30ff !important;
}

/* ============================================
   MARKDOWN CONTENT
   ============================================ */
.markdown a, [class*="markdown"] a {
    color: #b860ff !important;
}

.markdown a:hover, [class*="markdown"] a:hover {
    color: #9b30ff !important;
}

.markdown blockquote {
    border-left-color: #9b30ff !important;
    color: #a0a0a0 !important;
}

.markdown code {
    background-color: #1a1a1a !important;
    color: #b860ff !important;
}
}
